local observedGeometryArt = {}

local function Changed(housingContextChanged, event)
    local navigation = APR.navigation
    if
        not housingContextChanged
        and not APR.ActiveRoute
        and not (APR.Services and (APR.Services.active or APR.Services.request))
        and not (navigation and (navigation.search or (event == "UNIT_PHASE" and navigation.destination)))
        and event ~= "GARRISON_UPDATE"
    then
        if
            event == "QUEST_TURNED_IN"
            or event == "PLAYER_ENTERING_WORLD"
            or event == "ZONE_CHANGED_NEW_AREA"
            or event == "NEIGHBORHOOD_MAP_DATA_UPDATED"
            or event == "UNIT_PHASE"
        then
            observedGeometryArt = {}
            Data:InvalidatePositionCache()
        end
        return
    end
    -- Quest, bag and dialogue events refresh character observations, not the
    -- world's static topology. Keep map projections and the shared zone index
    -- unless the client actually changed phase geometry.
    local mapID = C_Map and Call(C_Map.GetBestMapForUnit, "player")
    if not Number(mapID) then mapID = nil end
    local artID = mapID and Call(C_Map.GetMapArtID, mapID)
    if not Number(artID) then artID = nil end
    local geometryChanged = event == "NEIGHBORHOOD_MAP_DATA_UPDATED" or event == "GARRISON_UPDATE" or event == "UNIT_PHASE"
    if mapID and artID then
        geometryChanged = geometryChanged or observedGeometryArt[mapID] ~= artID
        observedGeometryArt[mapID] = artID
    elseif event == "QUEST_TURNED_IN" then
        -- Clients without readable map art still refresh on a possible phase
        -- transition, while ordinary UI/log events retain static geometry.
        geometryChanged = true
    end
    if geometryChanged then
        if APR.InvalidatePlayerZoneCache then
            APR:InvalidatePlayerZoneCache(true)
        else
            Data:InvalidatePositionCache()
        end
    end
    local cancelledHousing = false
    if housingContextChanged and navigation and navigation.Cancel then
        -- Secure housing buttons must not keep an old house identity. A
        -- background candidate may contain housing even when the published
        -- trip does not: discard that candidate without deleting its guidance.
        local pending = navigation.search ~= nil or (navigation.GetState and navigation:GetState() == "planning")
        local active = navigation.GetActiveStep and navigation:GetActiveStep()
        local function HousingStep(step)
            local kind = step and step.action and step.action.type or (step and step.kind)
            return kind == "housing" or kind == "housing_return"
        end--[[APR_DIAG]]; HousingStep = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterEvents.lua:74:HousingStep#2", HousingStep)--[[/APR_DIAG]]
        local affected = HousingStep(active)
        for index = navigation.cursor or 1, #(navigation.queue or {}) do
            if HousingStep(navigation.queue[index]) then
                affected = true
                break
            end
        end
        if
            affected
            or (
                pending
                and (not navigation.DiscardCandidate or not navigation.IsNavigating or not navigation:IsNavigating())
            )
        then
            navigation:Cancel("housing_changed")
            cancelledHousing = true
        elseif pending then
            navigation:DiscardCandidate("housing_changed")
            cancelledHousing = true
        end
    end
    if navigation and navigation.ForceRefresh then
        local transition = event == "PLAYER_ENTERING_WORLD"
            or event == "ZONE_CHANGED_NEW_AREA"
            or event == "ZONE_CHANGED"
        navigation:ForceRefresh(transition and "world_transition" or event)
    end
    if cancelledHousing and navigation.RequestUpdate then navigation:RequestUpdate() end
end--[[APR_DIAG]]; Changed = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterEvents.lua:25:Changed#1", Changed)--[[/APR_DIAG]]

function Adapter:CheckBindLanding(afterLoading)
    local pending = self.pendingBindLanding
    if not pending then return end
    local now = GetTime and GetTime() or 0
    local position = PlayerPosition()
    if
        now > pending.deadline
        or Call(UnitIsDeadOrGhost, "player") == true
        or Text(Call(GetBindLocation)) ~= pending.name
    then
        self.pendingBindLanding = nil
    elseif position then
        local source = pending.from
        if
            afterLoading
            or (
                source
                and (
                    source.instanceID ~= position.instanceID
                    or (source.x - position.x) ^ 2 + (source.y - position.y) ^ 2 >= 10000
                )
            )
        then
            self.pendingBindLanding = nil
            self:CaptureBind()
            Changed()
        end
    end
    if not self.pendingBindLanding and self.bindTicker then
        self.bindTicker:Cancel()
        self.bindTicker = nil
    end
end--[[APR_DIAG]]; Adapter.CheckBindLanding = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterEvents.lua:108:Adapter:CheckBindLanding#3", Adapter.CheckBindLanding)--[[/APR_DIAG]]

