    APR:RegisterMessage("APR_MAP_UPDATE", --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterEvents.lua:157:callback#4", --[[/APR_DIAG]]function() Adapter:QueueWaypointRefresh() end--[[APR_DIAG]])--[[/APR_DIAG]])
end

