    frame:RegisterEvent("PLAYER_HOUSE_LIST_UPDATED")
    frame:RegisterEvent("NEIGHBORHOOD_MAP_DATA_UPDATED")
    frame:RegisterEvent("TRACKED_HOUSE_CHANGED")
end
